//! The edges of the `client` and `commands` generators: the names a model can use that the
//! generated code also wants, the entities that get fewer calls, and the paths that are not
//! a plain plural. Each model here is generated by every shipped generator and built with
//! the real compiler, because the failure these guard against is a crate that does not
//! compile, and no assertion about text finds that.

mod common;

use common::{Scratch, assert_builds, assert_formatted, generate_all, generated_workspace};

/// An entity whose members are named after what the generated code itself binds or flags,
/// with a text key, and relations named after the fixed verbs.
const AWKWARD: &str = r#"{ "metadata.root": { "package": "edge", "children": [
  { "object.entity": { "name": "Command", "children": [
    { "source.rdb": { "@table": "commands" } },
    { "field.string": { "name": "code", "@required": true, "@filterable": true, "@sortable": true } },
    { "identity.primary": { "name": "pk", "@fields": ["code"] } },
    { "field.string": { "name": "json", "@filterable": true } },
    { "field.string": { "name": "body" } },
    { "field.string": { "name": "query", "@sortable": true } },
    { "field.string": { "name": "client" } },
    { "field.string": { "name": "command" } },
    { "field.string": { "name": "found" } },
    { "field.string": { "name": "api" } },
    { "field.string": { "name": "help" } },
    { "field.string": { "name": "id" } },
    { "field.string": { "name": "filter", "@filterable": true } },
    { "field.string": { "name": "sort", "@filterable": true, "@sortable": true } },
    { "field.int": { "name": "limit", "@filterable": true } },
    { "field.boolean": { "name": "count", "@filterable": true } },
    { "field.string": { "name": "self" } },
    { "field.string": { "name": "match", "@filterable": true, "@sortable": true } },
    { "field.double": { "name": "ratio", "isArray": true } },
    { "field.int": { "name": "scores", "isArray": true } },
    { "relationship.association": { "name": "delete", "@cardinality": "many", "@objectRef": "Client",
        "@through": "CommandClient" } },
    { "relationship.association": { "name": "listOfClients", "@cardinality": "many", "@objectRef": "Client",
        "@through": "CommandClient" } }
  ] } },
  { "object.entity": { "name": "Client", "children": [
    { "source.rdb": { "@table": "clients" } },
    { "field.uuid": { "name": "id" } },
    { "identity.primary": { "name": "pk", "@fields": ["id"] } },
    { "field.string": { "name": "name", "@required": true } }
  ] } },
  { "object.entity": { "name": "CommandClient", "children": [
    { "source.rdb": { "@table": "command_clients" } },
    { "field.string": { "name": "commandCode", "@required": true } },
    { "field.uuid": { "name": "clientId", "@required": true } },
    { "identity.primary": { "name": "pk", "@fields": ["commandCode", "clientId"] } },
    { "identity.reference": { "name": "fkCommand", "@fields": "commandCode", "@references": "Command" } },
    { "identity.reference": { "name": "fkClient", "@fields": "clientId", "@references": "Client" } }
  ] } },
  { "object.entity": { "name": "Unstored", "children": [
    { "field.long": { "name": "id" } },
    { "identity.primary": { "name": "pk", "@fields": ["id"] } }
  ] } }
] } }"#;

#[test]
fn names_the_generated_code_also_wants_still_build() {
    let p = Scratch::project("client-edges", &[("metaobjects/meta.edge.json", AWKWARD)]);
    generate_all(&p, &[]);

    // A text key is borrowed by the client and owned by the command line.
    let client = p.read("generated/edge_client/src/command.rs");
    assert!(
        client.contains("pub async fn get(&self, id: &str)"),
        "{client}"
    );
    assert!(
        client.contains("pub const PATH: &'static str = \"commands\";"),
        "{client}"
    );
    // A relation named after a verb keeps its own name in the path and gets `_of` as a call.
    assert!(
        client.contains("pub async fn delete(&self, id: &str)"),
        "{client}"
    );
    assert!(
        client.contains("pub async fn delete_of(&self, id: &str)"),
        "{client}"
    );
    assert!(
        client.contains("related(Self::PATH, id, \"delete\")"),
        "{client}"
    );
    assert!(
        client.contains("related(Self::PATH, id, \"listOfClients\")"),
        "{client}"
    );
    assert!(
        client.contains("pub fn match_eq(mut self, value: &str)"),
        "{client}"
    );

    let commands = p.read("generated/edge_cli/src/command.rs");
    assert!(
        commands.contains("#[command(name = \"delete-of\")]"),
        "{commands}"
    );
    assert!(
        commands.contains("#[command(name = \"list-of-clients\")]"),
        "{commands}"
    );
    // `--json` and `--help` are taken, so those members are set through the body only; a
    // member named like a local of `run` is bound under another name.
    assert!(
        !commands.contains("        help: Option<String>,"),
        "{commands}"
    );
    assert_eq!(
        commands.matches("        json: Option<String>,").count(),
        2,
        "{commands}"
    );
    assert!(commands.contains("body: body_flag"), "{commands}");
    // `update <id>` takes the key as its argument, so the member `id` has no flag there.
    assert_eq!(
        commands.matches("        id: Option<String>,").count(),
        1,
        "{commands}"
    );

    // A composite key has no single id: the collection, and nothing per row.
    let junction = p.read("generated/edge_client/src/command_client.rs");
    assert!(junction.contains("pub async fn create("), "{junction}");
    assert!(!junction.contains("pub async fn get("), "{junction}");
    assert!(!junction.contains("pub async fn delete("), "{junction}");
    let junction = p.read("generated/edge_cli/src/command_client.rs");
    assert!(
        junction.contains("    Create {") && !junction.contains("    Get {"),
        "{junction}"
    );

    // An entity nothing stores is not served: a model type, and no client or command.
    assert!(p.exists("generated/edge/src/unstored.rs"));
    assert!(!p.exists("generated/edge_client/src/unstored.rs"));
    assert!(!p.exists("generated/edge_cli/src/unstored.rs"));

    let ws = generated_workspace("client-edges-ws", &p, None);
    assert_formatted(&ws);
    assert_builds(&ws, "the awkward-names model");
}

#[test]
fn a_model_with_nothing_served_gets_no_client_and_no_transport() {
    let model = r#"{ "metadata.root": { "package": "plain", "children": [
      { "object.value": { "name": "Point", "children": [
        { "field.double": { "name": "x", "@required": true } }
      ] } }
    ] } }"#;
    let p = Scratch::project("client-none", &[("metaobjects/meta.plain.json", model)]);
    generate_all(&p, &[]);
    assert!(p.exists("generated/plain/src/point.rs"));
    for absent in ["plain_client", "plain_cli", "meta_client", "meta_cli"] {
        assert!(
            !p.exists(&format!("generated/{absent}")),
            "{absent} was written for nothing"
        );
    }
}

#[test]
fn a_subtype_of_a_single_table_hierarchy_is_reached_under_its_base() {
    let p = Scratch::project("client-tph", &common::FITNESS_PROJECT);
    generate_all(&p, &[]);
    let base = p.read("generated/fitness_client/src/auth.rs");
    assert!(
        base.contains("pub const PATH: &'static str = \"auths\";"),
        "{base}"
    );
    let subtype = p.read("generated/fitness_client/src/bridge_auth.rs");
    assert!(
        subtype.contains("pub const PATH: &'static str = \"auths/bridge\";"),
        "{subtype}"
    );
}
